-- Destination guides written by administrators in the admin console and read by the planner.
-- Additive: a new table only. The previous release never reads it.
CREATE TABLE iam.guides (
    id uuid PRIMARY KEY,
    name varchar(120) NOT NULL CHECK (length(btrim(name)) > 0),
    country varchar(100) NOT NULL DEFAULT '',
    country_code varchar(2) CHECK (country_code ~ '^[A-Z]{2}$'),
    destination_provider varchar(16) NOT NULL CHECK (destination_provider IN ('GOOGLE','MAPBOX')),
    destination_place_id varchar(255) NOT NULL CHECK (length(btrim(destination_place_id)) > 0),
    destination_name varchar(200) NOT NULL,
    destination_lat double precision NOT NULL CHECK (destination_lat BETWEEN -90 AND 90),
    destination_lng double precision NOT NULL CHECK (destination_lng BETWEEN -180 AND 180),
    description text NOT NULL DEFAULT '' CHECK (length(description) <= 4000),
    cover_place_id varchar(300) NOT NULL,
    -- The editor document: categories, list headers, places and the block text (markdown).
    content jsonb NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PUBLISHED')),
    version bigint NOT NULL DEFAULT 0,
    created_by uuid REFERENCES iam.users(id) ON DELETE SET NULL,
    updated_by uuid REFERENCES iam.users(id) ON DELETE SET NULL,
    published_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ck_guides_published_at CHECK (status <> 'PUBLISHED' OR published_at IS NOT NULL)
);
-- One guide per destination.
CREATE UNIQUE INDEX uq_guides_destination ON iam.guides (destination_provider, destination_place_id);
CREATE INDEX ix_guides_status_country ON iam.guides (status, country, name);

-- Frozen copy of the Bangkok guide the planner prototype shipped with, published so travelers keep seeing it.
