:"Noodle Shop","tags":["Pad thai","Local favourite"]},"ChIJe5jdmNeZ4jARNzb36wTdDws":{"id":"GOOGLE:ChIJe5jdmNeZ4jARNzb36wTdDws","provider":"GOOGLE","providerPlaceId":"ChIJe5jdmNeZ4jARNzb36wTdDws","name":"Somtam Nua","address":"392, 12-14 Rama I Rd, Pathum Wan, Bangkok 10330, Thailand","lat":13.7444073,"lng":100.5342979,"primaryType":"thai_restaurant","category":"Thai Restaurant","tags":["Isan","Casual"]},"ChIJN8lqeBSZ4jAReT6qXHgmoas":{"id":"GOOGLE:ChIJN8lqeBSZ4jAReT6qXHgmoas","provider":"GOOGLE","providerPlaceId":"ChIJN8lqeBSZ4jAReT6qXHgmoas","name":"Krua Apsorn","address":"169 Dinso Rd, Phra Nakhon, Bangkok 10200, Thailand","lat":13.7552154,"lng":100.5016545,"primaryType":"thai_restaurant","category":"Thai Restaurant","tags":["Thai","Family style"]},"ChIJb73JxSOZ4jARHgl4zhyCrLE":{"id":"GOOGLE:ChIJb73JxSOZ4jARHgl4zhyCrLE","provider":"GOOGLE","providerPlaceId":"ChIJb73JxSOZ4jARHgl4zhyCrLE","name":"Nai Mong Hoi Tod","address":"539 Phlap Phla Chai Rd, Pom Prap Sattru Phai, Bangkok 10100, Thailand","lat":13.7421953,"lng":100.510739,"primaryType":"chinese_restaurant","category":"Chinese Restaurant","tags":["Chinatown","Street food"]},"ChIJ--rTNief4jARBGLQAL_tfHw":{"id":"GOOGLE:ChIJ--rTNief4jARBGLQAL_tfHw","provider":"GOOGLE","providerPlaceId":"ChIJ--rTNief4jARBGLQAL_tfHw","name":"Polo Fried Chicken","address":"137/1-3 Soi Polo, Pathum Wan, Bangkok 10330, Thailand","lat":13.7322268,"lng":100.545961,"primaryType":"thai_restaurant","category":"Thai Restaurant","tags":["Fried chicken","Isan"]},"ChIJ67MqRQSZ4jARLVzfkPJOWRg":{"id":"GOOGLE:ChIJ67MqRQSZ4jARLVzfkPJOWRg","provider":"GOOGLE","providerPlaceId":"ChIJ67MqRQSZ4jARLVzfkPJOWRg","name":"Err Urban Rustic Thai","address":"2/4 Sukhumvit Rd, Khlong Toei, Bangkok 10110, Thailand","lat":13.7261498,"lng":100.5749863,"primaryType":"thai_restaurant","category":"Thai Restaurant","tags":["Thai","Drinks"]},"ChIJ-eIsmEme4jARJj2YJYuFOAA":{"id":"GOOGLE:ChIJ-eIsmEme4jARJj2YJYuFOAA","provider":"GOOGLE","providerPlaceId":"ChIJ-eIsmEme4jARJj2YJYuFOAA","name":"Wattana Panich","address":"336 338 Thanon Ekkamai, Watthana, Bangkok 10110, Thailand","lat":13.7341825,"lng":100.5876467,"primaryType":"thai_restaurant","category":"Thai Restaurant","tags":["Noodles","Local favourite"]},"ChIJs6CnycSY4jAR5cqJZjPOsgs":{"id":"GOOGLE:ChIJs6CnycSY4jAR5cqJZjPOsgs","provider":"GOOGLE","providerPlaceId":"ChIJs6CnycSY4jAR5cqJZjPOsgs","name":"Mandarin Oriental, Bangkok","address":"48 Oriental Ave, Bang Rak, Bangkok 10500, Thailand","lat":13.7236158,"lng":100.5143168,"primaryType":"hotel","category":"Hotel","tags":["Luxury","Riverside"]},"ChIJp8e_7NOY4jARN83NYCd7tVc":{"id":"GOOGLE:ChIJp8e_7NOY4jARN83NYCd7tVc","provider":"GOOGLE","providerPlaceId":"ChIJp8e_7NOY4jARN83NYCd7tVc","name":"The Peninsula Bangkok","address":"333 Charoen Nakhon Rd, Khlong San, Bangkok 10600, Thailand","lat":13.7231212,"lng":100.5108006,"primaryType":"hotel","category":"Hotel","tags":["Luxury","River views"]},"ChIJqcNXkyaZ4jAR6PgpLK1RNzI":{"id":"GOOGLE:ChIJqcNXkyaZ4jAR6PgpLK1RNzI","provider":"GOOGLE","providerPlaceId":"ChIJqcNXkyaZ4jAR6PgpLK1RNzI","name":"Capella Bangkok","address":"300/2 Charoen Krung Rd, Sathon, Bangkok 10120, Thailand","lat":13.7131047,"lng":100.5110225,"primaryType":"hotel","category":"Hotel","tags":["Luxury","Riverside"]},"ChIJbw__g9-b4jAR3iYpzC9gRoI":{"id":"GOOGLE:ChIJbw__g9-b4jAR3iYpzC9gRoI","provider":"GOOGLE","providerPlaceId":"ChIJbw__g9-b4jAR3iYpzC9gRoI","name":"The Siam","address":"3/2 Khao Rd, Dusit, Bangkok 10300, Thailand","lat":13.7811383,"lng":100.5059915,"primaryType":"hotel","category":"Hotel","tags":["Boutique","Riverside"]},"ChIJJUys49ye4jAR-TlV_Qsxx3Y":{"id":"GOOGLE:ChIJJUys49ye4jAR-TlV_Qsxx3Y","provider":"GOOGLE","providerPlaceId":"ChIJJUys49ye4jAR-TlV_Qsxx3Y","name":"Rosewood Bangkok","address":"1041/38 Phloen Chit Rd, Pathum Wan, Bangkok 10330, Thailand","lat":13.7433455,"lng":100.5489627,"primaryType":"hotel","category":"Hotel","tags":["Luxury","BTS access"]},"ChIJPfeHijq44jARW7bwbPBz3v4":{"id":"GOOGLE:ChIJPfeHijq44jARW7bwbPBz3v4","provider":"GOOGLE","providerPlaceId":"ChIJPfeHijq44jARW7bwbPBz3v4","name":"The Sukhothai Bangkok","address":"13/3 S Sathon Rd, Sathon, Bangkok 10120, Thailand","lat":13.7229783,"lng":100.540869,"primaryType":"hotel","category":"Hotel","tags":["Luxury","Quiet"]},"ChIJFYHsCL-Y4jAR4bcD5G4o1Ks":{"id":"GOOGLE:ChIJFYHsCL-Y4jAR4bcD5G4o1Ks","provider":"GOOGLE","providerPlaceId":"ChIJFYHsCL-Y4jAR4bcD5G4o1Ks","name":"Chatrium Hotel Riverside","address":"28 Charoen Krung Rd, Bang Kho Laem, Bangkok 10120, Thailand","lat":13.7108744,"lng":100.5095152,"primaryType":"hotel","category":"Hotel","tags":["Mid-range","Family friendly"]},"ChIJp6e4xdOY4jARUt6nA2RdZDA":{"id":"GOOGLE:ChIJp6e4xdOY4jARUt6nA2RdZDA","provider":"GOOGLE","providerPlaceId":"ChIJp6e4xdOY4jARUt6nA2RdZDA","name":"Lub d Bangkok Silom","address":"4 Decho Rd, Bang Rak, Bangkok 10500, Thailand","lat":13.727169,"lng":100.52491,"primaryType":"hostel","category":"Hostel","tags":["Budget","Hostel"]}},"body":"<div data-embed=\"placeList\" data-list-id=\"visit\"></div>\n\nPlan around the heat: temples first thing in the morning, a long lunch somewhere air-conditioned, then markets and rooftops after dark.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJPzZsMU6Z4jARQUzvk913bCo\"></div>\n\nThe former royal residence and home of the Emerald Buddha at Wat Phra Kaew. Go at opening time to beat the heat and the tour groups, and cover shoulders and knees.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJgcxFcQWZ4jARLsIR9Qia9H0\"></div>\n\nA short walk south of the Grand Palace, known for its 46-metre reclining Buddha and as the home of traditional Thai massage, which you can book on site.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJaSv_6gaZ4jARnbiUVn6Z_YY\"></div>\n\nThe Temple of Dawn rises over the west bank of the Chao Phraya, its spire covered in porcelain. Cross by ferry from Tha Tien pier, and stay for sunset views from the far bank.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJ3fiD6BSc4jARS324hNeR8ZE\"></div>\n\nOne of the world's largest weekend markets, with thousands of stalls selling clothes, crafts, plants and snacks. Open Saturday and Sunday; arrive early before it gets hot.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJWVT7hDKZ4jARGJOhe21RhOk\"></div>\n\nSix traditional teak houses assembled by the American silk trader who disappeared in 1967, set in a quiet garden near National Stadium BTS. Visits are by guided tour.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJG7BL7Saf4jARNmn5AQiyAaw\"></div>\n\nCentral Bangkok's green lung, with a lake, paddle boats, outdoor gyms and resident monitor lizards. Best early morning or around sunset, when locals come to run.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJrdfOcJOZ4jAR1Grh5w74V1g\"></div>\n\nNeon signs, gold shops and the city's most famous street food strip. Come after dark, when the stalls along Yaowarat Road are at their busiest.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJGzV2mdKY4jARdIb62T7BoE4\"></div>\n\nAn open-air observation deck 314 metres up, with a glass floor over the edge. Book a sunset slot for the best light over the river.\n\n<div data-embed=\"placeList\" data-list-id=\"eat\"></div>\n\nBangkok eats best at street level. The famous shophouses queue for an hour or more at dinner, so go mid-afternoon.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJaxq89xaZ4jARQtKhE1uqq9c\"></div>\n\nThe goggle-wearing street-food chef with a Michelin star, famous for crab omelette and drunken noodles. Expect long queues and high prices for a shophouse.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJxU5YeBaZ4jARvm8EVZYGjGk\"></div>\n\nPad thai since 1966, cooked over charcoal at the front of the shop. Try the version wrapped in a thin egg omelette, with fresh orange juice.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJe5jdmNeZ4jARNzb36wTdDws\"></div>\n\nA Siam Square favourite for Isan food: papaya salad, fried chicken and sticky rice at fair prices. Handy between shopping malls.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJN8lqeBSZ4jAReT6qXHgmoas\"></div>\n\nHome-style central Thai cooking near Democracy Monument. Known for its crab meat omelette and stir-fried crab with yellow chilli.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJb73JxSOZ4jARHgl4zhyCrLE\"></div>\n\nA small Chinatown shop serving crispy oyster and mussel omelettes straight off a wide iron pan.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJ--rTNief4jARBGLQAL_tfHw\"></div>\n\nGarlic-crusted fried chicken with som tam and sticky rice, a short walk from Lumphini Park.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJ67MqRQSZ4jARLVzfkPJOWRg\"></div>\n\nThai drinking snacks and small plates done carefully, with a good list of local craft beer and rice whisky cocktails.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJ-eIsmEme4jARJj2YJYuFOAA\"></div>\n\nBeef noodle soup from a broth that has been simmering in the same pot for decades. A lunchtime institution on Ekkamai.\n\n<div data-embed=\"placeList\" data-list-id=\"stay\"></div>\n\nStay by the river for the old town and the boat shuttles, or along the BTS for shopping and nightlife.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJs6CnycSY4jAR5cqJZjPOsgs\"></div>\n\nThe city's grand dame on the river since 1876, with its own boat shuttle and a famous afternoon tea in the Authors' Lounge.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJp8e_7NOY4jARN83NYCd7tVc\"></div>\n\nEvery room looks over the Chao Phraya. A free shuttle boat crosses to Saphan Taksin BTS station.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJqcNXkyaZ4jAR6PgpLK1RNzI\"></div>\n\nA low-rise riverside resort where every room faces the water, with two well-regarded restaurants.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJbw__g9-b4jAR3iYpzC9gRoI\"></div>\n\nAn art deco hideaway in old Dusit, filled with the owner's antiques, with a Muay Thai ring and a private pier.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJJUys49ye4jAR-TlV_Qsxx3Y\"></div>\n\nA modern tower with a direct skywalk to Phloen Chit BTS, good for shopping trips around Chit Lom.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJPfeHijq44jARW7bwbPBz3v4\"></div>\n\nCalm, low-rise rooms around lotus ponds on South Sathorn, close to Lumphini MRT.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJFYHsCL-Y4jAR4bcD5G4o1Ks\"></div>\n\nLarge rooms with river views at mid-range prices, plus a free shuttle boat to Sathorn pier.\n\n<div data-embed=\"guidePlace\" data-place-id=\"ChIJp6e4xdOY4jARUt6nA2RdZDA\"></div>\n\nA sociable hostel with dorms and private rooms, a short walk from Chong Nonsi BTS."}$guide$::jsonb, 'PUBLISHED', now());
